package placement

// The English ladder. Keys are "en/<level>/<skill><n>" and stable forever:
// answer rows of finished tests keep referring to them.
func init() {
	add("en", A1, []Question{
		{Key: "en/A1/g1", Skill: SkillGrammar, Prompt: "She ___ from Spain.", Options: []string{"is", "are", "am", "be"}, Answer: "is"},
		{Key: "en/A1/g2", Skill: SkillGrammar, Prompt: "___ you like coffee?", Options: []string{"Do", "Does", "Is", "Are"}, Answer: "Do"},
		{Key: "en/A1/g3", Skill: SkillGrammar, Prompt: "They ___ football every Sunday.", Options: []string{"play", "plays", "playing", "played"}, Answer: "play"},
		{Key: "en/A1/g4", Skill: SkillGrammar, Prompt: "There ___ a book on the table.", Options: []string{"is", "are", "have", "has"}, Answer: "is"},
		{Key: "en/A1/v1", Skill: SkillVocabulary, Prompt: "What is the opposite of 'hot'?", Options: []string{"cold", "warm", "cool", "wet"}, Answer: "cold"},
		{Key: "en/A1/v2", Skill: SkillVocabulary, Prompt: "An apple is a ___.", Options: []string{"fruit", "vegetable", "drink", "dessert"}, Answer: "fruit"},
		{Key: "en/A1/v3", Skill: SkillVocabulary, Prompt: "Monday, Tuesday, ___, Thursday.", Options: []string{"Wednesday", "Friday", "Sunday", "Saturday"}, Answer: "Wednesday"},
		{Key: "en/A1/v4", Skill: SkillVocabulary, Prompt: "How do you say 'спасибо' in English?", Options: []string{"thanks", "please", "sorry", "hello"}, Answer: "thanks"},
		{Key: "en/A1/r1", Skill: SkillReading, Text: "My name is Anna. I am 25 years old. I live in Rome.", Prompt: "Where does Anna live?", Options: []string{"In Rome", "In Paris", "In London", "In Madrid"}, Answer: "In Rome"},
		{Key: "en/A1/r2", Skill: SkillReading, Text: "Tom has two brothers. They all like pizza.", Prompt: "How many brothers does Tom have?", Options: []string{"Two", "One", "Three", "None"}, Answer: "Two"},
		{Key: "en/A1/r3", Skill: SkillReading, Text: "The shop opens at 9 a.m. and closes at 6 p.m.", Prompt: "When does the shop close?", Options: []string{"At 6 p.m.", "At 9 a.m.", "At noon", "At 8 p.m."}, Answer: "At 6 p.m."},
		{Key: "en/A1/r4", Skill: SkillReading, Text: "It is raining, so Maria takes an umbrella.", Prompt: "Why does Maria take an umbrella?", Options: []string{"Because it is raining", "Because it is sunny", "Because she is cold", "Because she is late"}, Answer: "Because it is raining"},
	})

	add("en", A2, []Question{
		{Key: "en/A2/g1", Skill: SkillGrammar, Prompt: "I ___ TV yesterday evening.", Options: []string{"watched", "watch", "watching", "watches"}, Answer: "watched"},
		{Key: "en/A2/g2", Skill: SkillGrammar, Prompt: "She ___ to Paris last year.", Options: []string{"went", "goes", "going", "go"}, Answer: "went"},
		{Key: "en/A2/g3", Skill: SkillGrammar, Prompt: "We ___ in this house since 2015.", Options: []string{"have lived", "live", "lived", "are living"}, Answer: "have lived"},
		{Key: "en/A2/g4", Skill: SkillGrammar, Prompt: "___ milk do you want — a little or a lot?", Options: []string{"How much", "How many", "What", "Which"}, Answer: "How much"},
		{Key: "en/A2/v1", Skill: SkillVocabulary, Prompt: "'Cheap' means ___.", Options: []string{"not expensive", "not heavy", "not big", "not old"}, Answer: "not expensive"},
		{Key: "en/A2/v2", Skill: SkillVocabulary, Prompt: "Which of these is a vegetable?", Options: []string{"carrot", "apple", "bread", "cheese"}, Answer: "carrot"},
		{Key: "en/A2/v3", Skill: SkillVocabulary, Prompt: "'Weather' is ___.", Options: []string{"sun, rain, wind and so on", "what you wear", "a kind of food", "a sport"}, Answer: "sun, rain, wind and so on"},
		{Key: "en/A2/v4", Skill: SkillVocabulary, Prompt: "To 'arrive' means to ___.", Options: []string{"reach a place", "leave a place", "wait", "sleep"}, Answer: "reach a place"},
		{Key: "en/A2/r1", Skill: SkillReading, Text: "Daniel works in a bank. He starts at eight and finishes at five. On Saturdays he plays tennis with his son.", Prompt: "What does Daniel do on Saturdays?", Options: []string{"He plays tennis", "He works", "He swims", "He sleeps"}, Answer: "He plays tennis"},
		{Key: "en/A2/r2", Skill: SkillReading, Text: "The museum is closed on Mondays, but it is open every other day. Entry is free for students.", Prompt: "Who can enter the museum for free?", Options: []string{"Students", "Everyone", "Teachers", "Children"}, Answer: "Students"},
		{Key: "en/A2/r3", Skill: SkillReading, Text: "Lisa wants to buy a new laptop, but she thinks they are too expensive. She will wait for the sale.", Prompt: "Why doesn't Lisa buy a laptop now?", Options: []string{"Because they are too expensive", "Because she already has one", "Because the shop is closed", "Because she doesn't like laptops"}, Answer: "Because they are too expensive"},
		{Key: "en/A2/r4", Skill: SkillReading, Text: "Yesterday was my birthday. I got a bike from my parents and a book from my friend Kate.", Prompt: "What did Kate give the writer?", Options: []string{"A book", "A bike", "A card", "Nothing"}, Answer: "A book"},
	})

	add("en", B1, []Question{
		{Key: "en/B1/g1", Skill: SkillGrammar, Prompt: "If it ___ tomorrow, we'll stay at home.", Options: []string{"rains", "will rain", "raining", "rain"}, Answer: "rains"},
		{Key: "en/B1/g2", Skill: SkillGrammar, Prompt: "This is the man ___ car was stolen.", Options: []string{"whose", "who", "which", "his"}, Answer: "whose"},
		{Key: "en/B1/g3", Skill: SkillGrammar, Prompt: "You ___ smoke here; it's forbidden.", Options: []string{"mustn't", "don't have to", "couldn't", "might not"}, Answer: "mustn't"},
		{Key: "en/B1/g4", Skill: SkillGrammar, Prompt: "I ___ here for ten years now, and I still love it.", Options: []string{"have been working", "work", "am working", "worked"}, Answer: "have been working"},
		{Key: "en/B1/v1", Skill: SkillVocabulary, Prompt: "'Generous' means ___.", Options: []string{"willing to give", "very rich", "very strict", "careful with money"}, Answer: "willing to give"},
		{Key: "en/B1/v2", Skill: SkillVocabulary, Prompt: "To 'postpone' means to ___.", Options: []string{"delay to a later time", "cancel completely", "start immediately", "repeat"}, Answer: "delay to a later time"},
		{Key: "en/B1/v3", Skill: SkillVocabulary, Prompt: "A 'refund' is ___.", Options: []string{"money you get back", "a discount", "a receipt", "a loan"}, Answer: "money you get back"},
		{Key: "en/B1/v4", Skill: SkillVocabulary, Prompt: "'Despite the rain' means ___.", Options: []string{"although it rained", "because it rained", "it stopped raining", "it didn't rain"}, Answer: "although it rained"},
		{Key: "en/B1/r1", Skill: SkillReading, Text: "The new train line, which opens next spring, will cut the journey to the coast from two hours to forty minutes. Critics, however, warn that tickets will be too expensive for daily commuters.", Prompt: "What do critics say about the new train line?", Options: []string{"The tickets will be too expensive", "It will be too slow", "It should open sooner", "It is badly built"}, Answer: "The tickets will be too expensive"},
		{Key: "en/B1/r2", Skill: SkillReading, Text: "According to the study, people who sleep fewer than six hours a night find it harder to concentrate at work and are more likely to catch colds.", Prompt: "What does the study say about short sleep?", Options: []string{"It makes concentration harder and colds more likely", "It helps people work faster", "It has no effect on health", "It prevents colds"}, Answer: "It makes concentration harder and colds more likely"},
		{Key: "en/B1/r3", Skill: SkillReading, Text: "When Emma arrived at the airport, she realised she had left her passport at home. She had to take a taxi back, and she nearly missed her flight.", Prompt: "Why did Emma almost miss her flight?", Options: []string{"She had to go back home for her passport", "Her taxi broke down", "Her flight left early", "She lost her ticket"}, Answer: "She had to go back home for her passport"},
		{Key: "en/B1/r4", Skill: SkillReading, Text: "The restaurant looks ordinary from the street, but the food is excellent and surprisingly cheap. Book ahead, though: it fills up quickly at the weekend.", Prompt: "What does the writer advise?", Options: []string{"To book a table in advance", "To avoid the restaurant", "To go only on weekdays", "To order the cheapest dish"}, Answer: "To book a table in advance"},
	})

	add("en", B2, []Question{
		{Key: "en/B2/g1", Skill: SkillGrammar, Prompt: "No sooner ___ the door than the phone rang.", Options: []string{"had I closed", "I closed", "did I close", "I had closed"}, Answer: "had I closed"},
		{Key: "en/B2/g2", Skill: SkillGrammar, Prompt: "I'd rather you ___ me the truth.", Options: []string{"told", "tell", "to tell", "had told"}, Answer: "told"},
		{Key: "en/B2/g3", Skill: SkillGrammar, Prompt: "The report ___ by the committee next week.", Options: []string{"will be reviewed", "reviews", "will review", "has reviewed"}, Answer: "will be reviewed"},
		{Key: "en/B2/g4", Skill: SkillGrammar, Prompt: "He denied ___ the documents.", Options: []string{"taking", "to take", "take", "taken"}, Answer: "taking"},
		{Key: "en/B2/v1", Skill: SkillVocabulary, Prompt: "'Ubiquitous' means ___.", Options: []string{"present everywhere", "very rare", "extremely loud", "hard to see"}, Answer: "present everywhere"},
		{Key: "en/B2/v2", Skill: SkillVocabulary, Prompt: "To 'alleviate' a problem means to ___.", Options: []string{"make it less severe", "solve it completely", "ignore it", "cause it"}, Answer: "make it less severe"},
		{Key: "en/B2/v3", Skill: SkillVocabulary, Prompt: "A 'paradox' is ___.", Options: []string{"a statement that contradicts itself", "a kind of poem", "a medical condition", "a mathematical tool"}, Answer: "a statement that contradicts itself"},
		{Key: "en/B2/v4", Skill: SkillVocabulary, Prompt: "To 'scrutinise' means to ___.", Options: []string{"examine carefully", "admire quietly", "destroy slowly", "announce publicly"}, Answer: "examine carefully"},
		{Key: "en/B2/r1", Skill: SkillReading, Text: "While electric cars are often praised as a clean alternative, their production still carries a heavy environmental cost, particularly in the mining of lithium for batteries. Until recycling improves, the claim that they are impact-free remains optimistic at best.", Prompt: "What is the writer's position?", Options: []string{"Electric cars are not entirely impact-free", "Electric cars are worse than petrol cars", "Battery production should be banned", "Recycling has already solved the problem"}, Answer: "Electric cars are not entirely impact-free"},
		{Key: "en/B2/r2", Skill: SkillReading, Text: "The town council's decision to close the library was met with outrage. Campaigners argue that the building serves as a community hub, not merely a place to borrow books, and point out that visitor numbers have actually risen over the past three years.", Prompt: "Why are campaigners against the closure?", Options: []string{"The library is a valued community space with rising use", "The books are too old", "The council needs the building", "They want a bigger car park"}, Answer: "The library is a valued community space with rising use"},
		{Key: "en/B2/r3", Skill: SkillReading, Text: "Researchers believe the inscription dates back to the sixth century, although some scholars dispute this, noting that the script resembles work from the ninth century more closely.", Prompt: "Why do some scholars disagree about the date?", Options: []string{"The script looks like ninth-century work", "The inscription is forged", "Sixth-century work is rare", "The stone is damaged"}, Answer: "The script looks like ninth-century work"},
		{Key: "en/B2/r4", Skill: SkillReading, Text: "Had the company invested in cybersecurity a year earlier, the breach that exposed thousands of customer records might have been prevented. Instead, the warning signs were ignored, and the cost — both financial and reputational — has been severe.", Prompt: "According to the text, the breach happened because ___.", Options: []string{"warnings were ignored", "the records were encrypted", "the investment came too early", "customers were careless"}, Answer: "warnings were ignored"},
	})

	add("en", C1, []Question{
		{Key: "en/C1/g1", Skill: SkillGrammar, Prompt: "Not until the evidence emerged ___ that he had been wrong.", Options: []string{"did he admit", "he admitted", "he had admitted", "had he admitted"}, Answer: "did he admit"},
		{Key: "en/C1/g2", Skill: SkillGrammar, Prompt: "___ the delay, the project was delivered on budget.", Options: []string{"Despite", "Although", "However", "Whereas"}, Answer: "Despite"},
		{Key: "en/C1/g3", Skill: SkillGrammar, Prompt: "It's high time the government ___ action.", Options: []string{"took", "takes", "take", "will take"}, Answer: "took"},
		{Key: "en/C1/g4", Skill: SkillGrammar, Prompt: "She spoke as though she ___ the whole story.", Options: []string{"had known", "knew", "knows", "would know"}, Answer: "had known"},
		{Key: "en/C1/v1", Skill: SkillVocabulary, Prompt: "'Ephemeral' means ___.", Options: []string{"lasting a very short time", "extremely strong", "very old", "widely known"}, Answer: "lasting a very short time"},
		{Key: "en/C1/v2", Skill: SkillVocabulary, Prompt: "To 'equivocate' means to ___.", Options: []string{"avoid giving a clear answer", "make things equal", "speak loudly", "correct a mistake"}, Answer: "avoid giving a clear answer"},
		{Key: "en/C1/v3", Skill: SkillVocabulary, Prompt: "'Pragmatic' describes someone who is ___.", Options: []string{"practical rather than idealistic", "stubborn", "highly emotional", "inexperienced"}, Answer: "practical rather than idealistic"},
		{Key: "en/C1/v4", Skill: SkillVocabulary, Prompt: "An 'oxymoron' is ___.", Options: []string{"a phrase combining contradictory terms", "a kind of dinosaur", "a grammatical error", "a poetic metre"}, Answer: "a phrase combining contradictory terms"},
		{Key: "en/C1/r1", Skill: SkillReading, Text: "The prevailing narrative that the city's revival was driven by private investment overlooks the decade of grassroots organising that preceded it. Community groups had long pressed for the very reforms developers later claimed as their own — a fact conspicuously absent from most contemporary accounts.", Prompt: "What does the writer argue?", Options: []string{"Grassroots organising, not private investment, drove the revival", "Private investors deserve the credit", "The city has not revived", "Contemporary accounts are accurate"}, Answer: "Grassroots organising, not private investment, drove the revival"},
		{Key: "en/C1/r2", Skill: SkillReading, Text: "While the policy's intentions are laudable, its implementation has been anything but. Funding arrived late, guidance was contradictory, and many of those it was designed to help remain, two years on, worse off than before.", Prompt: "What does the writer say about the policy?", Options: []string{"It was badly implemented and failed its targets", "It was well funded but unpopular", "It should never have been proposed", "Its intentions were cynical"}, Answer: "It was badly implemented and failed its targets"},
		{Key: "en/C1/r3", Skill: SkillReading, Text: "Her latest novel resists easy classification: it borrows the trappings of a thriller while ultimately subverting every convention of the genre. Some critics have found this disorienting; others regard it as the book's greatest strength.", Prompt: "Why do critics differ over the novel?", Options: []string{"Its genre-defying approach divides opinion", "It is too long", "It follows conventions too closely", "It lacks a plot"}, Answer: "Its genre-defying approach divides opinion"},
		{Key: "en/C1/r4", Skill: SkillReading, Text: "Attributing the empire's collapse to a single cause does violence to the historical record. Economic strain, external pressure and internal fragmentation interacted in ways that render any monocausal account untenable, however seductive such explanations may be.", Prompt: "What is the writer's view of single-cause explanations?", Options: []string{"They distort a complex reality", "They are useful despite being simple", "They are supported by the record", "They explain economics best"}, Answer: "They distort a complex reality"},
	})

	add("en", C2, []Question{
		{Key: "en/C2/g1", Skill: SkillGrammar, Prompt: "Were the allegations to be substantiated, the minister ___ have to resign.", Options: []string{"would", "will", "would had", "shall"}, Answer: "would"},
		{Key: "en/C2/g2", Skill: SkillGrammar, Prompt: "Seldom ___ such unanimity in the committee.", Options: []string{"has there been", "there has been", "it has been", "was it"}, Answer: "has there been"},
		{Key: "en/C2/g3", Skill: SkillGrammar, Prompt: "The proposal was rejected out of ___, without any real consideration.", Options: []string{"hand", "mind", "court", "spite"}, Answer: "hand"},
		{Key: "en/C2/g4", Skill: SkillGrammar, Prompt: "I'd just as soon you ___ mention this to anyone.", Options: []string{"didn't", "don't", "hadn't", "won't"}, Answer: "didn't"},
		{Key: "en/C2/v1", Skill: SkillVocabulary, Prompt: "'Perspicacious' means ___.", Options: []string{"having keen insight", "extremely stubborn", "overly talkative", "physically strong"}, Answer: "having keen insight"},
		{Key: "en/C2/v2", Skill: SkillVocabulary, Prompt: "To 'obfuscate' means to ___.", Options: []string{"deliberately confuse", "secretly record", "slowly repair", "publicly praise"}, Answer: "deliberately confuse"},
		{Key: "en/C2/v3", Skill: SkillVocabulary, Prompt: "Something done 'perfunctorily' is done ___.", Options: []string{"without real care or interest", "with great precision", "at great speed", "for a high price"}, Answer: "without real care or interest"},
		{Key: "en/C2/v4", Skill: SkillVocabulary, Prompt: "'Sangfroid' refers to ___.", Options: []string{"calmness under pressure", "a love of music", "cold weather", "rigid discipline"}, Answer: "calmness under pressure"},
		{Key: "en/C2/r1", Skill: SkillReading, Text: "What is often overlooked in debates about automation is that the technology does not so much eliminate work as reconfigure it — frequently in ways that redistribute rather than reduce effort, transferring the cognitive load from operator to supervisor.", Prompt: "According to the writer, automation ___.", Options: []string{"redistributes work rather than removing it", "eliminates more work than expected", "reduces the overall effort", "makes supervision unnecessary"}, Answer: "redistributes work rather than removing it"},
		{Key: "en/C2/r2", Skill: SkillReading, Text: "The biography's central weakness is not its scholarship, which is impeccable, but its reticence: having gained unprecedented access to its subject's correspondence, it proves strangely reluctant to draw the conclusions that access affords.", Prompt: "What does the reviewer criticise?", Options: []string{"The book fails to draw on its unique material", "The scholarship is poor", "The correspondence is fake", "The subject is boring"}, Answer: "The book fails to draw on its unique material"},
		{Key: "en/C2/r3", Skill: SkillReading, Text: "To describe the novel as merely autobiographical is to miss its artistry: the self it portrays is as much an invention as any of its characters, a composite stitched together from memory, omission and desire.", Prompt: "What does the writer claim about the novel?", Options: []string{"Its 'self' is a constructed fiction", "It is purely factual", "Its characters are real people", "It contains no memory"}, Answer: "Its 'self' is a constructed fiction"},
		{Key: "en/C2/r4", Skill: SkillReading, Text: "However compelling the analogy, it founders on a single point: markets punish error, whereas the institution in question is insulated from it. To borrow the language of one to describe the other is, then, less illumination than evasion.", Prompt: "Why does the analogy fail, in the writer's view?", Options: []string{"The institution is shielded from the consequences markets impose", "Markets are not well understood", "The language is too technical", "Institutions never make errors"}, Answer: "The institution is shielded from the consequences markets impose"},
	})
}
